import React, { useState } from "react";
import {
  Checkbox,
  Box,
  Flex,
  Text,
  IconButton,
  HStack,
  Badge,
} from "@chakra-ui/react";
import { EditIcon, DeleteIcon, TimeIcon } from "@chakra-ui/icons";
import "./Action.css";
import ModalDeleteAction from "./ModalDeleteAction";
import ModalEditAction from "./ModalEditAction";
import { format } from "date-fns";
import { editAction } from "../../actions/action_actions";
import { useDispatch } from "react-redux";

function Action({ action = {} }) {
  const [openModalEdit, setOpenModalEdit] = useState(false);
  const [openModalDelete, setOpenModalDelete] = useState(false);
  const dispatch = useDispatch();

  if (!action || typeof action !== "object") return null; // Guard clause

  const {
    description = "",
    startDate,
    priority = "low",
    type,
    completed = {},
    _id,
    fieldId,
  } = action;

  const isCompletedToday = Boolean(completed?.status);

  const handleModalDelete = (e) => {
    setOpenModalDelete(!openModalDelete);
  };

  const handleModalEdit = (e) => {
    setOpenModalEdit(!openModalEdit);
  };

  const updateCompletedStatus = async () => {
    const nextStatus = !isCompletedToday;

    const updatedPayload = {
      ...action,
      id: _id, // Ensures compatibility if your API expects `id`
      _id: _id,
      completed: {
        status: nextStatus,
        completionDate: nextStatus ? new Date() : null,
      },
    };

    try {
      await dispatch(editAction(updatedPayload));
    } catch (err) {
      console.error("Failed to toggle action status:", err);
    }
  };

  const getThemeColors = () => {
    if (isCompletedToday)
      return {
        border: "green.400",
        bg: "green.50",
        glow: "rgba(72, 187, 120, 0.15)",
      };
    const p = priority?.toLowerCase();
    if (p === "high")
      return {
        border: "yellow.300",
        bg: "yellow.300",
        glow: "rgba(212, 211, 120, 0.15)",
      };
    if (p === "medium")
      return {
        border: "orange.400",
        bg: "orange.50",
        glow: "rgba(237, 137, 54, 0.15)",
      };
    return {
      border: "gray.300",
      bg: "gray.50",
      glow: "rgba(160, 174, 192, 0.1)",
    };
  };

  const colors = getThemeColors();

  return (
    <Box
      className="action__glass-card"
      w="100%"
      p={6}
      mb={4}
      bg={isCompletedToday ? colors.bg : "white"}
      border="1px solid"
      borderColor={isCompletedToday ? "green.200" : "gray.100"}
      borderLeft="6px solid"
      borderLeftColor={colors.border}
      borderRadius="2xl"
      boxShadow={`0 10px 25px -5px ${colors.glow}, 0 8px 10px -6px rgba(0,0,0,0.03)`}
      _hover={{
        transform: "translateY(-4px)",
        boxShadow: `0 20px 35px -5px ${colors.glow}, 0 12px 16px -8px rgba(0,0,0,0.05)`,
        borderColor: isCompletedToday ? "green.300" : "gray.200",
      }}
      transition="all 0.3s cubic-bezier(0.4, 0, 0.2, 1)"
    >
      <Flex direction="column" gap={4} w="100%">
        {/* Main Row: Checkbox, Text Description, and Management Controls */}
        <Flex
          width="100%"
          alignItems="start"
          justifyContent="space-between"
          gap={4}
        >
          <HStack spacing={4} alignItems="start" flex="1">
            <Checkbox
              id={`cb-${_id}`}
              isChecked={isCompletedToday}
              onChange={updateCompletedStatus}
              colorScheme="green"
              size="lg"
              mt="3px"
              transform="scale(1.2)"
              borderRadius="md"
            />
            <Text
              className="action__description"
              color={isCompletedToday ? "gray.400" : "gray.800"}
              fontWeight="bold"
              fontSize="lg"
              lineHeight="base"
              letterSpacing="wide"
            >
              {description}
            </Text>
          </HStack>

          {/* Quick Control Buttons Panel */}
          <HStack spacing={1} shrink={0} bg="gray.50" borderRadius="xl" p={1}>
            <IconButton
              icon={<EditIcon />}
              size="sm"
              variant="ghost"
              colorScheme="blue"
              onClick={handleModalEdit}
              aria-label="Edit action"
              borderRadius="lg"
            />
            <ModalEditAction
              openModalEdit={openModalEdit}
              handleModalEdit={handleModalEdit}
              data={action}
            />

            <IconButton
              icon={<DeleteIcon />}
              size="sm"
              variant="ghost"
              colorScheme="red"
              onClick={handleModalDelete}
              aria-label="Delete action"
              borderRadius="lg"
            />
            <ModalDeleteAction
              openModalDelete={openModalDelete}
              handleModalDelete={handleModalDelete}
              data={action}
            />
          </HStack>
        </Flex>

        {/* Footer Row: Categories and timestamps */}
        <Flex
          justify="space-between"
          alignItems="center"
          borderTop="1px dashed"
          borderColor="gray.100"
          pt={3}
        >
          <HStack spacing={3}>
            <Badge
              variant="solid"
              bg={
                isCompletedToday
                  ? "green.500"
                  : `${colors.border.split(".")[0]}.500`
              }
              color="white"
              px={3}
              py={1}
              borderRadius="full"
              fontSize="xs"
              fontWeight="extrabold"
              letterSpacing="wider"
            >
              {priority}
            </Badge>

            <Badge
              variant="subtle"
              colorScheme="purple"
              px={3}
              py={1}
              borderRadius="full"
              fontSize="xs"
              fontWeight="bold"
            >
              {type}
            </Badge>
          </HStack>

          {/* Clock Display Format with Native Time Icon */}
          <HStack spacing={1.5} color="gray.400">
            <TimeIcon boxSize="3.5px" />
            <Text fontSize="xs" fontWeight="bold" letterSpacing="wide">
              {format(new Date(startDate), "HH:mm")} &bull;{" "}
              {format(new Date(startDate), "dd MMM")}
            </Text>
          </HStack>
        </Flex>
      </Flex>
    </Box>
  );
}

export default React.memo(Action);
